export class ApiClientError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(status: number, message: string, body: unknown) {
    super(message);
    this.name = "ApiClientError";
    this.status = status;
    this.body = body;
  }

  static async fromResponse(response: Response): Promise<ApiClientError> {
    const body = await parseResponseBody(response);
    const message = extractErrorMessage(body) ?? `HTTP ${response.status}`;
    return new ApiClientError(response.status, message, body);
  }
}

export async function ensureOk<T>(response: Response): Promise<T> {
  if (!response.ok) {
    throw await ApiClientError.fromResponse(response);
  }

  return (await response.json()) as T;
}

export function extractErrorMessage(payload: unknown): string | null {
  if (typeof payload === "string" && payload.trim().length > 0) {
    return payload;
  }

  if (typeof payload !== "object" || payload === null) {
    return null;
  }

  const candidate = payload as Record<string, unknown>;
  const message = candidate.message ?? candidate.detail ?? candidate.error;

  return typeof message === "string" && message.trim().length > 0 ? message : null;
}

export function describeApiError(error: unknown, fallbackMessage: string): string {
  if (error instanceof ApiClientError) {
    return extractErrorMessage(error.body) ?? error.message ?? fallbackMessage;
  }

  if (error instanceof Error && error.message.trim().length > 0) {
    return error.message;
  }

  return fallbackMessage;
}

async function parseResponseBody(response: Response): Promise<unknown> {
  const contentType = response.headers.get("content-type") ?? "";

  if (contentType.includes("application/json")) {
    return response.json();
  }

  const text = await response.text();
  return text.length > 0 ? text : null;
}
