import { ensureOk } from "./http";

export interface UploadDocumentResult {
  document_id: string;
  correlation_id: string;
  status: string;
}

export interface UploadDocumentInput {
  file: File;
  correlationId: string;
}

export interface DocumentsApi {
  uploadDocument(input: UploadDocumentInput): Promise<UploadDocumentResult>;
}

export interface CreateDocumentsApiOptions {
  baseUrl?: string;
  fetchImpl?: typeof fetch;
  authHeaders?: () => Record<string, string>;
}

export function createDocumentsApi(options: CreateDocumentsApiOptions = {}): DocumentsApi {
  const baseUrl = options.baseUrl ?? "";
  const fetchImpl = options.fetchImpl ?? fetch;
  const authHeaders = options.authHeaders ?? (() => ({}));

  return {
    async uploadDocument(input: UploadDocumentInput): Promise<UploadDocumentResult> {
      const formData = new FormData();
      formData.append("file", input.file);

      const response = await fetchImpl(`${baseUrl}/documents`, {
        method: "POST",
        body: formData,
        headers: {
          ...authHeaders(),
          "X-Correlation-ID": input.correlationId
        }
      });

      return ensureOk<UploadDocumentResult>(response);
    }
  };
}
