import { ApiClientError } from "../api/http";

export type RedirectTarget = "/login" | "/unauthorized" | null;

export function resolveRedirectTarget(error: unknown): RedirectTarget {
  if (!(error instanceof ApiClientError)) {
    return null;
  }

  if (error.status === 401) {
    return "/login";
  }

  if (error.status === 403) {
    return "/unauthorized";
  }

  return null;
}

export function redirectNoticeFor(target: RedirectTarget): string | null {
  if (target === "/login") {
    return "Sessione non valida. Reindirizzamento al login in corso.";
  }

  if (target === "/unauthorized") {
    return "Accesso non autorizzato. Reindirizzamento alla pagina dedicata in corso.";
  }

  return null;
}
