import { DEFAULT_UPLOAD_CONSTRAINTS, FileValidationResult, UploadConstraints } from "./model";

export function inputAcceptAttribute(constraints: UploadConstraints = DEFAULT_UPLOAD_CONSTRAINTS): string {
  return constraints.allowedExtensions.join(",");
}

export function validateSelectedFile(
  file: File | null,
  constraints: UploadConstraints = DEFAULT_UPLOAD_CONSTRAINTS
): FileValidationResult {
  if (file === null) {
    return {
      ok: false,
      message: "Seleziona un file da caricare."
    };
  }

  if (file.size > constraints.maxSizeBytes) {
    return {
      ok: false,
      message: "Il file supera il limite di 20 MB."
    };
  }

  if (!isAllowedType(file, constraints)) {
    return {
      ok: false,
      message: "Formato non supportato. Sono ammessi PDF, DOCX, JPG e PNG."
    };
  }

  return {
    ok: true,
    message: null
  };
}

function isAllowedType(file: File, constraints: UploadConstraints): boolean {
  const normalizedMimeType = file.type.trim().toLowerCase();
  const normalizedName = file.name.trim().toLowerCase();

  if (constraints.allowedMimeTypes.includes(normalizedMimeType)) {
    return true;
  }

  return constraints.allowedExtensions.some((extension) => normalizedName.endsWith(extension));
}
