import React from "react";

import { DocumentsApi, UploadDocumentResult } from "../../shared/api/documents";
import { describeApiError } from "../../shared/api/http";
import { redirectNoticeFor, resolveRedirectTarget } from "../../shared/auth/route-guards";
import { FileDropzone } from "../../shared/ui/file-dropzone";
import { StatusBanner } from "../../shared/ui/status-banner";
import { DEFAULT_UPLOAD_CONSTRAINTS, UploadConstraints } from "./model";
import { inputAcceptAttribute, validateSelectedFile } from "./validation";

export interface UploadPageProps {
  documentsApi: DocumentsApi;
  constraints?: UploadConstraints;
  onNavigate?: (target: string) => void;
  correlationIdFactory?: () => string;
}

export function UploadPage(props: UploadPageProps): React.JSX.Element {
  const constraints = props.constraints ?? DEFAULT_UPLOAD_CONSTRAINTS;
  const correlationIdFactory = props.correlationIdFactory ?? defaultCorrelationIdFactory;
  const [selectedFile, setSelectedFile] = React.useState<File | null>(null);
  const [validationMessage, setValidationMessage] = React.useState<string | null>(null);
  const [uploadMessage, setUploadMessage] = React.useState<string | null>(null);
  const [redirectMessage, setRedirectMessage] = React.useState<string | null>(null);
  const [uploadResult, setUploadResult] = React.useState<UploadDocumentResult | null>(null);
  const [isUploading, setIsUploading] = React.useState(false);

  function applyFileSelection(file: File | null): void {
    const validation = validateSelectedFile(file, constraints);
    setUploadMessage(null);
    setRedirectMessage(null);
    setUploadResult(null);

    if (!validation.ok) {
      setSelectedFile(null);
      setValidationMessage(validation.message);
      return;
    }

    setSelectedFile(file);
    setValidationMessage(null);
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();

    const validation = validateSelectedFile(selectedFile, constraints);
    if (!validation.ok) {
      setValidationMessage(validation.message);
      return;
    }

    setIsUploading(true);
    setUploadMessage(null);
    setRedirectMessage(null);

    try {
      const result = await props.documentsApi.uploadDocument({
        file: selectedFile,
        correlationId: correlationIdFactory()
      });

      setUploadResult(result);
      setValidationMessage(null);
    } catch (error) {
      const redirectTarget = resolveRedirectTarget(error);

      if (redirectTarget !== null) {
        const notice = redirectNoticeFor(redirectTarget);
        setRedirectMessage(notice);
        props.onNavigate?.(redirectTarget);
      } else {
        setUploadMessage(describeApiError(error, "Errore durante il caricamento del documento."));
      }
    } finally {
      setIsUploading(false);
    }
  }

  return (
    <main className="mx-auto flex max-w-5xl flex-col gap-6 p-8">
      <header className="space-y-2">
        <p className="text-sm font-semibold uppercase tracking-wide text-slate-600">Upload documenti</p>
        <h1 className="text-3xl font-bold text-slate-950">Carica un documento</h1>
        <p className="max-w-3xl text-sm text-slate-700">
          Carica file PDF, DOCX, JPG o PNG fino a 20 MB. Dopo l&apos;upload riceverai il document_id e il link
          alla prossima azione operativa.
        </p>
      </header>

      <form className="grid gap-6 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm" onSubmit={handleSubmit}>
        <FileDropzone
          accept={inputAcceptAttribute(constraints)}
          disabled={isUploading}
          selectedFileName={selectedFile?.name}
          onFilesSelected={(files) => applyFileSelection(files[0] ?? null)}
        />

        <section className="grid gap-2 rounded-lg bg-slate-50 p-4 text-sm text-slate-700">
          <div>
            <span className="font-semibold">Tipi ammessi:</span> PDF, DOCX, JPG, PNG
          </div>
          <div>
            <span className="font-semibold">Dimensione massima:</span> 20 MB
          </div>
          <div>
            <span className="font-semibold">Stato selezione:</span>{" "}
            {selectedFile ? `${selectedFile.name} (${Math.ceil(selectedFile.size / 1024)} KB)` : "Nessun file selezionato"}
          </div>
        </section>

        {validationMessage ? (
          <StatusBanner title="Validazione client" tone="error">
            <p>{validationMessage}</p>
          </StatusBanner>
        ) : null}

        {uploadMessage ? (
          <StatusBanner title="Upload non riuscito" tone="error">
            <p>{uploadMessage}</p>
          </StatusBanner>
        ) : null}

        {redirectMessage ? (
          <StatusBanner title="Reindirizzamento" tone="info">
            <p>{redirectMessage}</p>
          </StatusBanner>
        ) : null}

        {uploadResult ? (
          <StatusBanner title="Documento caricato correttamente" tone="success">
            <dl className="grid gap-2">
              <div>
                <dt className="font-semibold">document_id</dt>
                <dd>{uploadResult.document_id}</dd>
              </div>
              <div>
                <dt className="font-semibold">correlation_id</dt>
                <dd>{uploadResult.correlation_id}</dd>
              </div>
              <div>
                <dt className="font-semibold">Stato</dt>
                <dd>{uploadResult.status}</dd>
              </div>
            </dl>
            <a
              className="mt-3 inline-flex rounded-md border border-emerald-700 px-4 py-2 font-medium text-emerald-800"
              href={`/workflow/inbox?document_id=${encodeURIComponent(uploadResult.document_id)}`}
            >
              Vai alla prossima azione
            </a>
          </StatusBanner>
        ) : null}

        <div className="flex justify-end">
          <button
            type="submit"
            disabled={isUploading}
            className="inline-flex min-w-48 items-center justify-center rounded-md bg-slate-900 px-4 py-3 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:bg-slate-400"
          >
            {isUploading ? "Caricamento in corso..." : "Carica documento"}
          </button>
        </div>
      </form>
    </main>
  );
}

function defaultCorrelationIdFactory(): string {
  if (typeof globalThis.crypto !== "undefined" && typeof globalThis.crypto.randomUUID === "function") {
    return globalThis.crypto.randomUUID();
  }

  return `corr-${Date.now()}`;
}
